  $('#care-launcher').hidden=!features.ai||mode==='care';$('#care-launcher').onclick=()=>openAI();
  $$('[data-ai]').forEach(b=>{b.hidden=!features.ai||mode==='care';b.onclick=()=>openAI(activeEntries().find(r=>r.id===b.dataset.ai)?.text||'');});$$('[data-companion]').forEach(b=>b.onclick=()=>mode==='care'?ctx.localReflect():openAI());
  $$('[data-notes]').forEach(b=>b.hidden=!features.notes);$$('[data-scrapbook],[data-voice],.notebook-filters,.media-mode-tabs').forEach(b=>b.hidden=!features.media);
  $('#main').querySelectorAll('.page-heading p,.page-heading .eyebrow').forEach(e=>e.hidden=true);
  const heading=$('#main .page-heading');if(heading&&['journal','insights','care','gallery'].includes(page)){heading.classList.add('mini-page-heading');heading.style.backgroundImage=`url('${artURL(page==='journal'?'journal-window':page==='insights'?'insight-ripples':'modes-corner')}')`;}
