export function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});
export async function makeShareImage({text,title,source,date,mood,profile,image,theme='meadow',language='zh'}){
 const c=document.createElement('canvas'),ctx=c.getContext('2d'),w=900,pad=70;ctx.font='34px serif';const lines=[];for(const para of String(text).split('\n')){let line='';for(const ch of para){if(line&&ctx.measureText(line+ch).width>w-pad*2){lines.push(line);line=ch;}else line+=ch;}lines.push(line);}if(lines.length>240)throw Error('文字较长，请先缩短再生成分享图。');c.width=w;c.height=Math.max(900,420+lines.length*58+(image?700:0));const colors={meadow:['#f6f7f2','#3c5848'],mist:['#f1f5f5','#3e6166'],paper:['#f7f1e8','#785a42'],night:['#17231d','#d3dfce']}[theme]||['#f6f7f2','#3c5848'];ctx.fillStyle=colors[0];ctx.fillRect(0,0,w,c.height);const art=await loadImage(artURL('meadow-river'));ctx.globalAlpha=.28;ctx.drawImage(art,0,0,w,290);ctx.globalAlpha=1;ctx.fillStyle=colors[1];ctx.font='24px sans-serif';ctx.fillText('liubai-alittlepause',pad,70);ctx.font='36px serif';ctx.fillText(title||'留白',pad,145);ctx.font='22px sans-serif';ctx.fillText([date,mood].filter(Boolean).join(' · '),pad,195);let y=300;if(image){const bitmap=await createImageBitmap(image);const h=Math.min(650,(w-2*pad)*bitmap.height/bitmap.width);ctx.drawImage(bitmap,pad,y,w-2*pad,h);bitmap.close();y+=h+55;}ctx.font='34px serif';for(const line of lines){ctx.fillText(line,pad,y);y+=58;}ctx.font='22px sans-serif';ctx.fillText(source||'',pad,y+25);if(profile){let x=pad;if(profile.avatar){const av=await loadImage(profile.avatar);ctx.save();ctx.beginPath();ctx.arc(pad+24,y+90,24,0,Math.PI*2);ctx.clip();ctx.drawImage(av,pad,y+66,48,48);ctx.restore();x+=65;}ctx.fillText(profile.nickname||'',x,y+96);}ctx.font='20px sans-serif';ctx.fillText(language==='zh'?'留白-情绪日记 · 记下心情与生活':'liubai-alittlepause · A little room for your day',pad,c.height-90);ctx.font='17px sans-serif';ctx.fillText('github.com/workstonedai-collab/liubai',pad,c.height-50);return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Image could not be created')),'image/png'));
}
function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});}
